var firebaseConfig={apiKey:"AIzaSyCxlrEqi41cmnb5HzoFRnLsSi68Tno6eLk",authDomain:"vendin-machine-routes.firebaseapp.com",projectId:"vendin-machine-routes",storageBucket:"vendin-machine-routes.firebasestorage.app",messagingSenderId:"1040142766651",appId:"1:1040142766651:web:900f3f10a729f59deac21e"};
firebase.initializeApp(firebaseConfig);
var db=firebase.firestore();
var MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
var loc='',locations={},masterItems={},warehouse={},machines={},allReports=[],slots=[],prevRestockMap={},slotTemplates={},editingTemplateLocId=null,editingItemId=null,editingLocId=null,purchaseLedger=[],templateSlots=[],editingReportId=null,isOnline=true,offlineQueue=[];

function showStatus(msg,type){var b=document.getElementById('statusBar');b.textContent=msg;b.className='sbar '+(type||'info');setTimeout(function(){b.className='sbar';},4000);}
function showToast(msg){var e=document.getElementById('toast');e.textContent=msg;e.classList.add('show');setTimeout(function(){e.classList.remove('show');},2500);}
function esc(v){return String(v||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;');}
function fmtDate(ts){var d=new Date(ts);return(d.getMonth()+1)+'/'+d.getDate()+'/'+d.getFullYear()+' '+d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}
function slugId(n){return n.trim().toLowerCase().replace(/[^a-z0-9]/g,'_').replace(/_+/g,'_');}

function fbGet(col,id){return db.collection(col).doc(id).get().then(function(s){return s.exists?Object.assign({id:s.id},s.data()):null;});}
function fbSet(col,id,data){return db.collection(col).doc(id).set(data);}
function fbAdd(col,data){return db.collection(col).add(data).then(function(r){return Object.assign({id:r.id},data);});}
function fbDel(col,id){return db.collection(col).doc(id).delete();}
function fbAll(col,ord,lim){var q=db.collection(col);if(ord)q=q.orderBy(ord,'desc');if(lim)q=q.limit(lim);return q.get().then(function(s){var r=[];s.forEach(function(d){r.push(Object.assign({id:d.id},d.data()));});return r;});}

function loadLocations(){return fbAll('locations').then(function(docs){locations={};docs.forEach(function(d){locations[d.id]=d;});if(!Object.keys(locations).length){var defs=[{id:'loc_1',name:'Location 1',address:''},{id:'loc_2',name:'Location 2',address:''},{id:'loc_3',name:'Location 3',address:''},{id:'loc_4',name:'Location 4',address:''},{id:'loc_5',name:'Location 5',address:''}];return Promise.all(defs.map(function(l){return fbSet('locations',l.id,l).then(function(){locations[l.id]=l;});}));}}).then(function(){if(!loc||!locations[loc])loc=Object.keys(locations).sort()[0]||'';});}
function loadMasterItems(){return fbAll('masterItems').then(function(docs){masterItems={};docs.forEach(function(d){masterItems[d.id]=d;});});}
function loadWarehouse(){return fbAll('warehouse').then(function(docs){warehouse={};docs.forEach(function(d){warehouse[d.id]=d;});});}
function loadMachines(){return fbAll('machines').then(function(docs){machines={};docs.forEach(function(d){machines[d.id]=d;});});}
function loadAllReports(){return fbAll('reports','timestamp').then(function(docs){allReports=docs;});}
function loadPurchaseLedger(){return fbAll('purchaseLedger','timestamp').then(function(docs){purchaseLedger=docs;});}
function loadSlotTemplates(){return fbAll('slotTemplates').then(function(docs){slotTemplates={};docs.forEach(function(d){slotTemplates[d.id]=d;});});}
function loadSlots(){return fbGet('slots',loc).then(function(s){slots=[];if(s&&s.slots)slots=s.slots;if(!slots.length&&slotTemplates[loc]&&slotTemplates[loc].slots&&slotTemplates[loc].slots.length){slots=slotTemplates[loc].slots.map(function(s){return Object.assign({},s,{arrival:'',restock:'',cost:warehouse[s.itemId]&&warehouse[s.itemId].avgCost?warehouse[s.itemId].avgCost:''});});}else if(!slots.length){slots=[{slot:'A1',itemId:'',arrival:'',restock:'',price:'',cost:''},{slot:'A2',itemId:'',arrival:'',restock:'',price:'',cost:''},{slot:'B1',itemId:'',arrival:'',restock:'',price:'',cost:''},{slot:'B2',itemId:'',arrival:'',restock:'',price:'',cost:''}];}else{slots=slots.map(function(s){return Object.assign({},s,{arrival:'',restock:'',cost:warehouse[s.itemId]&&warehouse[s.itemId].avgCost?warehouse[s.itemId].avgCost:s.cost||''});});}buildPrevRestockMap();renderAll();showPrevRestockNote();});}
function saveSlotsDB(){return fbSet('slots',loc,{slots:slots});}
function addLog(entry){return fbAdd('invLog',entry).catch(function(){});}
function recalcAvgCost(itemId){var entries=purchaseLedger.filter(function(e){return e.itemId===itemId;});if(!entries.length)return Promise.resolve();var tq=entries.reduce(function(s,e){return s+e.qty;},0);var tc=entries.reduce(function(s,e){return s+(e.qty*e.pricePaid);},0);var avg=tq>0?Math.round(tc/tq*1000)/1000:0;if(warehouse[itemId]){warehouse[itemId].avgCost=avg;return fbSet('warehouse',itemId,warehouse[itemId]);}return Promise.resolve();}

function updateConn(){var dot=document.getElementById('connDot');var txt=document.getElementById('connText');var bar=document.getElementById('connBar');if(isOnline){dot.style.background='#2d7a2d';txt.textContent='Online';bar.style.background='#d4edda';bar.style.color='#1a6b2a';}else{dot.style.background='#c0392b';txt.textContent='Offline';bar.style.background='#fde8e8';bar.style.color='#a32d2d';}}
function saveBackup(){try{localStorage.setItem('vt-slots',JSON.stringify(slots));localStorage.setItem('vt-loc',loc);localStorage.setItem('vt-date',document.getElementById('visitDate').value);}catch(e){}}
function loadBackup(){try{var bl=localStorage.getItem('vt-loc');var bs=localStorage.getItem('vt-slots');var bd=localStorage.getItem('vt-date');if(bl&&bl===loc&&bs){var p=JSON.parse(bs);if(p.some(function(s){return s.arrival||s.restock;})){if(confirm('Unsaved data found. Restore it?')){slots=p;if(bd)document.getElementById('visitDate').value=bd;buildPrevRestockMap();renderAll();showPrevRestockNote();showStatus('Data restored!','success');return;}}}}catch(e){}}
function clearBackup(){try{localStorage.removeItem('vt-slots');localStorage.removeItem('vt-loc');localStorage.removeItem('vt-date');}catch(e){}}
function loadQueue(){try{var q=localStorage.getItem('vt-queue');offlineQueue=q?JSON.parse(q):[];}catch(e){offlineQueue=[];}}
function saveQueue(){try{localStorage.setItem('vt-queue',JSON.stringify(offlineQueue));}catch(e){}}
function syncQueue(){if(!offlineQueue.length)return;showStatus('Syncing '+offlineQueue.length+' queued report(s)...','info');var failed=[];var p=Promise.resolve();offlineQueue.forEach(function(item){p=p.then(function(){return fbAdd('reports',item.data).catch(function(){failed.push(item);});});});p.then(function(){offlineQueue=failed;saveQueue();if(!failed.length){return loadAllReports().then(function(){buildPrevRestockMap();renderAll();showPrevRestockNote();showStatus('Reports synced!','success');});}else{showStatus(failed.length+' failed to sync.','error');}});}

var TABS=['sheet','history','monthly','inventory','items','locations'];
function showTab(t){TABS.forEach(function(n){document.getElementById('pane-'+n).style.display=n===t?'':'none';var nb=document.getElementById('nav-'+n);if(nb)nb.classList.toggle('active',n===t);var db2=document.getElementById('dtab-'+n);if(db2)db2.classList.toggle('active',n===t);});if(t==='history'){loadAllReports().then(function(){buildPrevRestockMap();renderHistory();});}if(t==='monthly'){loadAllReports().then(function(){populateMonthPills();renderMonthly();});}if(t==='inventory'){Promise.all([loadWarehouse(),loadMachines(),loadPurchaseLedger()]).then(function(){renderInventory();renderPurchaseList();});}if(t==='items'){loadMasterItems().then(function(){updateItemDropdowns();renderMasterItems();});}if(t==='locations'){loadSlotTemplates().then(function(){renderLocationList();});}}
TABS.forEach(function(t){var nb=document.getElementById('nav-'+t);if(nb)nb.addEventListener('click',function(){showTab(t);});var db2=document.getElementById('dtab-'+t);if(db2)db2.addEventListener('click',function(){showTab(t);});});

function buildLocOpts(selId,all){var el=document.getElementById(selId);if(!el)return;var locs=Object.values(locations).sort(function(a,b){return a.name.localeCompare(b.name);});el.innerHTML=(all?'<option value="all">All locations</option>':'')+locs.map(function(l){return'<option value="'+l.id+'">'+l.name+'</option>';}).join('');}
function updateLocDropdowns(){buildLocOpts('locSel',false);buildLocOpts('histLoc',true);buildLocOpts('monthLoc',true);document.getElementById('locSel').value=loc;}
function itemOptsStr(selectedId){var items=Object.values(masterItems).sort(function(a,b){return a.name.localeCompare(b.name);});return'<option value="">-- Select --</option>'+items.map(function(i){return'<option value="'+i.id+'"'+(i.id===selectedId?' selected':'')+'>'+i.name+'</option>';}).join('');}
function updateItemDropdowns(){var html=itemOptsStr('');var el=document.getElementById('invItemSel');if(el)el.innerHTML=html;renderAll();}

function getPrevReport(reportId){var rep=allReports.find(function(r){return r.id===reportId;});if(!rep)return null;var thisDate=rep.dateVal||'';var locReps=allReports.filter(function(r){return r.loc===rep.loc&&r.id!==reportId;}).sort(function(a,b){var da=a.dateVal||'',db2=b.dateVal||'';return da!==db2?db2.localeCompare(da):b.timestamp-a.timestamp;});return locReps.filter(function(r){var rd=r.dateVal||'';return rd<thisDate||(rd===thisDate&&r.timestamp<rep.timestamp);})[0]||null;}
function getPrevRestockFor(reportId,itemId,slot){var prevRep=getPrevReport(reportId);if(!prevRep)return null;var lines=prevRep.lineItems||[];if(slot){var exact=lines.find(function(l){return l.slot===slot&&l.itemId===itemId;});if(exact&&exact.restock!==''&&exact.restock!==null)return parseFloat(exact.restock);}return null;}
function getBaselineRep(){var visitDate=document.getElementById('visitDate').value;var lrs=allReports.filter(function(r){return r.loc===loc;}).sort(function(a,b){var da=a.dateVal||'',db2=b.dateVal||'';return da!==db2?db2.localeCompare(da):b.timestamp-a.timestamp;});if(!lrs.length)return null;if(visitDate){var before=lrs.filter(function(r){return(r.dateVal||'')<visitDate;});return before.length?before[0]:null;}return lrs[0]||null;}
function buildPrevRestockMap(){prevRestockMap={};var base=getBaselineRep();if(!base)return;(base.lineItems||[]).forEach(function(l){if(l.itemId&&l.restock!==''&&l.restock!==null)prevRestockMap[(l.slot||'')+'|'+l.itemId]=parseFloat(l.restock);});}
function getPrevRestock(slot,iId){return prevRestockMap.hasOwnProperty((slot||'')+'|'+iId)?prevRestockMap[(slot||'')+'|'+iId]:null;}
function calcSold(s){var a=parseFloat(s.arrival);if(isNaN(a))return null;var base=getBaselineRep();if(base&&s.slot){var prev=base.lineItems&&base.lineItems.find(function(l){return l.slot===s.slot;});if(prev&&prev.itemId&&prev.itemId!==s.itemId)return null;}var p=getPrevRestock(s.slot,s.itemId);if(p===null)return null;return Math.max(0,p-a);}
function calcRow(s){var sold=calcSold(s);var price=parseFloat(s.price)||0;var cost=warehouse[s.itemId]&&warehouse[s.itemId].avgCost?warehouse[s.itemId].avgCost:(masterItems[s.itemId]?masterItems[s.itemId].cost:parseFloat(s.cost)||0);return{sold:sold,rev:sold!==null?sold*price:null,profit:sold!==null?sold*(price-cost):null};}
function showPrevRestockNote(){var note=document.getElementById('prevNote');var lrs=allReports.filter(function(r){return r.loc===loc;}).sort(function(a,b){return b.timestamp-a.timestamp;});if(!lrs.length){note.style.display='block';note.innerHTML='First visit. Enter qty & restock.';}else{note.style.display='block';note.innerHTML='Sold = prev restock - arrival. Last visit: <strong>'+lrs[0].date+'</strong>';}}

function renderAll(){renderMobileCards();renderDesktopTable();renderTotals();}
function renderMobileCards(){var c=document.getElementById('slotCards');if(!c)return;c.innerHTML=slots.map(function(s,i){var r=calcRow(s);var prev=getPrevRestock(s.slot,s.itemId);var it=s.itemId&&masterItems[s.itemId]?masterItems[s.itemId]:null;var soldStr=r.sold!==null?r.sold:prev===null?'-*':'-';return'<div class="slot-card"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.6rem"><span style="font-size:11px;font-weight:600;color:#888;text-transform:uppercase">Slot '+(s.slot||i+1)+'</span><button class="danger sm" data-action="removeslot" data-idx="'+i+'" style="background:transparent;color:#c0392b;border-color:#e8b4b0;padding:3px 8px">X</button></div><div class="grid2"><div><label style="font-size:11px;color:#666;margin-bottom:3px">Slot label</label><input type="text" value="'+esc(s.slot)+'" placeholder="A1" data-idx="'+i+'" data-field="slot"/></div><div><label style="font-size:11px;color:#666;margin-bottom:3px">Item</label><select data-idx="'+i+'" data-field="itemId">'+itemOptsStr(s.itemId)+'</select></div></div><div class="grid2"><div><label style="font-size:11px;color:#666;margin-bottom:3px">Arrival qty</label><input type="number" value="'+esc(s.arrival)+'" placeholder="0" min="0" inputmode="numeric" class="arr" data-idx="'+i+'" data-field="arrival"/><span style="font-size:10px;color:#aaa;display:block;margin-top:2px;text-align:center">'+(prev!==null?'prev: '+prev:'no prior visit')+'</span></div><div><label style="font-size:11px;color:#666;margin-bottom:3px">Restock qty</label><input type="number" value="'+esc(s.restock)+'" placeholder="0" min="0" inputmode="numeric" class="rst" data-idx="'+i+'" data-field="restock"/></div></div><div style="margin-bottom:8px"><label style="font-size:11px;color:#666;margin-bottom:3px">Sell price ($)</label><input type="number" value="'+esc(s.price)+'" placeholder="'+(it?it.price.toFixed(2):'1.50')+'" step="0.25" min="0" inputmode="decimal" data-idx="'+i+'" data-field="price"/></div><div class="calc-row"><div class="calc-item"><div class="clabel">SOLD</div><div class="cval" style="color:'+(r.sold!==null&&r.sold>0?'#1a6b2a':'#888')+'">'+soldStr+'</div></div><div class="calc-item"><div class="clabel">REVENUE</div><div class="cval">'+(r.rev!==null?'$'+r.rev.toFixed(2):'-')+'</div></div><div class="calc-item"><div class="clabel">PROFIT</div><div class="cval" style="color:'+(r.profit===null?'#888':r.profit<0?'#a32d2d':'#1a6b2a')+'">'+(r.profit!==null?'$'+r.profit.toFixed(2):'-')+'</div></div></div></div>';}).join('');}
function renderDesktopTable(){var b=document.getElementById('slotBody');if(!b)return;b.innerHTML=slots.map(function(s,i){var r=calcRow(s);var prev=getPrevRestock(s.slot,s.itemId);var it=s.itemId&&masterItems[s.itemId]?masterItems[s.itemId]:null;return'<tr><td><input type="text" value="'+esc(s.slot)+'" placeholder="A1" data-idx="'+i+'" data-field="slot"/></td><td><select data-idx="'+i+'" data-field="itemId">'+itemOptsStr(s.itemId)+'</select></td><td class="acol"><input type="number" value="'+esc(s.arrival)+'" placeholder="0" min="0" style="text-align:center" data-idx="'+i+'" data-field="arrival"/>'+(prev!==null?'<span style="font-size:10px;color:#aaa;display:block;text-align:center">'+prev+'</span>':'')+'</td><td class="rcol"><input type="number" value="'+esc(s.restock)+'" placeholder="0" min="0" style="text-align:center" data-idx="'+i+'" data-field="restock"/></td><td><input type="number" value="'+esc(s.price)+'" placeholder="'+(it?it.price.toFixed(2):'1.50')+'" step="0.25" min="0" style="text-align:right" data-idx="'+i+'" data-field="price"/></td><td style="text-align:center">'+(r.sold!==null?'<span class="green">'+r.sold+'</span>':prev===null?'<span class="muted">-*</span>':'-')+'</td><td style="text-align:right">'+(r.rev!==null?'$'+r.rev.toFixed(2):'-')+'</td><td style="text-align:right">'+(r.profit!==null?'<span class="'+(r.profit<0?'red':'green')+'">$'+r.profit.toFixed(2)+'</span>':'-')+'</td><td><button class="danger sm" data-action="removeslot" data-idx="'+i+'" style="background:transparent;color:#c0392b;border:1px solid #e8b4b0">X</button></td></tr>';}).join('');}
function updateRowCalcs(i){renderTotals();}
function renderTotals(){var ts=0,tr=0,tp=0,has=false;slots.forEach(function(s){var r=calcRow(s);if(r.sold!==null){ts+=r.sold;tr+=r.rev;tp+=r.profit;has=true;}});var e1=document.getElementById('tot-sold');var e2=document.getElementById('tot-rev');var e3=document.getElementById('tot-profit');if(e1)e1.textContent=has?ts:'-';if(e2)e2.textContent=has?'$'+tr.toFixed(2):'-';if(e3){e3.textContent=has?'$'+tp.toFixed(2):'-';e3.className=has&&tp<0?'red':'green';}}

document.getElementById('saveLocBtn').addEventListener('click',function(){var name=document.getElementById('locNameInput').value.trim();var address=document.getElementById('locAddress').value.trim();if(!name){alert('Enter a location name.');return;}var isEdit=!!editingLocId;var id=editingLocId||('loc_'+slugId(name)+'_'+Date.now());var obj={id:id,name:name,address:address};locations[id]=obj;fbSet('locations',id,obj).then(function(){if(!loc)loc=id;cancelLocEdit();updateLocDropdowns();renderLocationList();showToast(isEdit?'Location updated!':'Location added!');editingLocId=null;});});
document.getElementById('cancelLocBtn').addEventListener('click',cancelLocEdit);
function cancelLocEdit(){editingLocId=null;document.getElementById('locNameInput').value='';document.getElementById('locAddress').value='';document.getElementById('locFormTitle').textContent='Add new location';document.getElementById('saveLocBtn').textContent='Add Location';document.getElementById('cancelLocBtn').style.display='none';}
function renderLocationList(){var locs=Object.values(locations).sort(function(a,b){return a.name.localeCompare(b.name);});var div=document.getElementById('locationList');if(!locs.length){div.innerHTML='<p class="muted" style="font-size:13px">No locations yet.</p>';return;}div.innerHTML=locs.map(function(l){return'<div class="arow"><div style="flex:1"><div style="font-weight:600;font-size:14px">'+l.name+'</div>'+(l.address?'<div class="muted" style="font-size:12px">'+l.address+'</div>':'')+'</div><div style="display:flex;gap:6px"><button class="sm" data-action="slots" data-id="'+l.id+'" style="color:#7B5EA7;border-color:#c4b0e8">Slots</button><button class="sm primary" data-action="editloc" data-id="'+l.id+'">Edit</button><button class="danger sm" data-action="delloc" data-id="'+l.id+'">Del</button></div></div>';}).join('');}

document.getElementById('histLoc').addEventListener('change',function(){var v=this.value;var wrap=document.getElementById('histRenameWrap');var inp=document.getElementById('histLocRename');if(v&&v!=='all'&&locations[v]){wrap.style.display='';inp.value=locations[v].name;}else{wrap.style.display='none';}renderHistory();});
document.getElementById('histLocRenameBtn').addEventListener('click',function(){var v=document.getElementById('histLoc').value;var name=document.getElementById('histLocRename').value.trim();if(!v||v==='all'||!name)return;locations[v].name=name;fbSet('locations',v,locations[v]).then(function(){updateLocDropdowns();document.getElementById('histLoc').value=v;showToast('Renamed!');renderHistory();});});

document.getElementById('saveItemBtn').addEventListener('click',function(){var name=document.getElementById('masterName').value.trim();var cat=document.getElementById('masterCat').value;var price=parseFloat(document.getElementById('masterPrice').value)||0;var cost=parseFloat(document.getElementById('masterCost').value)||0;var reorder=parseInt(document.getElementById('masterReorder').value)||0;if(!name){alert('Enter an item name.');return;}var id=editingItemId||slugId(name);var item={id:id,name:name,category:cat,price:price,cost:cost,reorder:reorder};masterItems[id]=item;fbSet('masterItems',id,item).then(function(){cancelItemEdit();updateItemDropdowns();renderMasterItems();showToast(editingItemId?'Item updated!':'Item added!');editingItemId=null;});});
document.getElementById('cancelItemBtn').addEventListener('click',cancelItemEdit);
function cancelItemEdit(){editingItemId=null;['masterName','masterPrice','masterCost','masterReorder'].forEach(function(id){document.getElementById(id).value='';});document.getElementById('masterCat').value='drink';document.getElementById('itemFormTitle').textContent='Add new item';document.getElementById('saveItemBtn').textContent='Add Item';document.getElementById('cancelItemBtn').style.display='none';}
document.getElementById('itemCatFilter').addEventListener('change',renderMasterItems);
function renderMasterItems(){var filter=document.getElementById('itemCatFilter').value;var items=Object.values(masterItems).filter(function(i){return filter==='all'||i.category===filter;}).sort(function(a,b){return a.name.localeCompare(b.name);});var div=document.getElementById('masterItemList');if(!items.length){div.innerHTML='<p class="muted" style="font-size:13px">No items yet.</p>';return;}div.innerHTML=items.map(function(it){return'<div class="arow"><div style="flex:1"><div style="font-weight:600;font-size:14px">'+it.name+' <span class="cpill '+(it.category==='drink'?'cdrink':'csnack')+'">'+it.category+'</span></div><div class="muted" style="font-size:12px;margin-top:2px">Sell: $'+it.price.toFixed(2)+' Cost: $'+it.cost.toFixed(2)+' Reorder: '+(it.reorder||'not set')+'</div></div><div style="display:flex;gap:6px"><button class="sm primary" data-action="edititem" data-id="'+it.id+'">Edit</button><button class="danger sm" data-action="delitem" data-id="'+it.id+'">Del</button></div></div>';}).join('');}

document.getElementById('addPurchaseBtn').addEventListener('click',function(){var itemId=document.getElementById('invItemSel').value;var qty=parseInt(document.getElementById('invQty').value);var pricePaid=parseFloat(document.getElementById('invCost').value);var reorderOvr=parseInt(document.getElementById('invReorder').value);if(!itemId||!qty||qty<1||isNaN(pricePaid)){alert('Fill in item, quantity, and price paid.');return;}var it=masterItems[itemId];if(!it)return;var ex=warehouse[itemId]||{id:itemId,qty:0,avgCost:0,reorder:it.reorder||0};var total=ex.qty+qty;ex.avgCost=total>0?Math.round(((ex.qty*ex.avgCost)+(qty*pricePaid))/total*1000)/1000:pricePaid;ex.qty=total;ex.reorder=!isNaN(reorderOvr)?reorderOvr:ex.reorder;warehouse[itemId]=ex;var ledger={itemId:itemId,itemName:it.name,qty:qty,pricePaid:pricePaid,timestamp:Date.now()};Promise.all([fbSet('warehouse',itemId,ex),fbAdd('purchaseLedger',ledger)]).then(function(res){purchaseLedger.unshift(res[1]);document.getElementById('invQty').value='';document.getElementById('invCost').value='';document.getElementById('invReorder').value='';renderInventory();renderPurchaseList();showToast(qty+' '+it.name+' added!');});});
document.getElementById('purchaseFilter').addEventListener('change',renderPurchaseList);

function renderInventory(){var totalMap={};Object.values(masterItems).forEach(function(it){totalMap[it.id]={id:it.id,name:it.name,warehouse:0,machine:0,reorder:it.reorder||0,avgCost:warehouse[it.id]?warehouse[it.id].avgCost:it.cost||0};});Object.values(warehouse).filter(function(w){return masterItems[w.id];}).forEach(function(w){if(totalMap[w.id]){totalMap[w.id].warehouse=w.qty;totalMap[w.id].avgCost=w.avgCost||0;totalMap[w.id].reorder=w.reorder||totalMap[w.id].reorder;}});Object.values(machines).forEach(function(mData){Object.values(mData).filter(function(m){return m.itemId&&masterItems[m.itemId];}).forEach(function(m){if(totalMap[m.itemId])totalMap[m.itemId].machine=(totalMap[m.itemId].machine||0)+m.qty;});});var totals=Object.values(totalMap).sort(function(a,b){return a.name.localeCompare(b.name);});var low=totals.filter(function(t){return t.reorder>0&&(t.warehouse+t.machine)<=t.reorder;}).length;var lel=document.getElementById('invLowCount');if(lel){lel.textContent=low>0?low+' low':'';lel.style.display=low>0?'block':'none';}var div=document.getElementById('totalStockList');if(!totals.length){div.innerHTML='<p class="muted" style="font-size:13px">No items yet.</p>';return;}div.innerHTML='<div style="display:grid;grid-template-columns:1fr 60px 72px 60px 36px;gap:4px;font-size:11px;font-weight:600;color:#888;text-transform:uppercase;padding:0 0 8px;border-bottom:1px solid #f0ede8;margin-bottom:2px"><span>Item</span><span style="text-align:center">Whouse</span><span style="text-align:center">Machines</span><span style="text-align:center">Total</span><span></span></div>'+totals.map(function(t){var total=t.warehouse+t.machine;var isLow=t.reorder>0&&total<=t.reorder&&total>0;var isOut=total===0;var badge=isOut?'<span class="sb sout">Out</span>':isLow?'<span class="sb slow">Low</span>':'';return'<div style="display:grid;grid-template-columns:1fr 60px 72px 60px 36px;gap:4px;align-items:center;padding:9px 0;border-bottom:1px solid #f0ede8"><div><div style="font-weight:500;font-size:14px">'+t.name+' '+badge+'</div>'+(t.avgCost>0?'<div class="muted" style="font-size:11px">Avg: $'+t.avgCost.toFixed(3)+'</div>':'')+'</div><div style="text-align:center;color:#888;font-weight:600">'+t.warehouse+'</div><div style="text-align:center;color:#1a6fc4;font-weight:600">'+t.machine+'</div><div style="text-align:center;font-weight:700;font-size:16px" class="'+(isOut?'red':isLow?'orange':'green')+'">'+total+'</div><div><button class="sm primary" data-action="editinv" data-id="'+t.id+'" style="padding:4px 8px">Edit</button></div></div>';}).join('');}
function renderPurchaseList(){var filterEl=document.getElementById('purchaseFilter');var items=Array.from(new Set(purchaseLedger.map(function(e){return e.itemId;}))).map(function(id){return{id:id,name:masterItems[id]?masterItems[id].name:id};}).sort(function(a,b){return a.name.localeCompare(b.name);});var cur=filterEl.value;filterEl.innerHTML='<option value="all">All items</option>'+items.map(function(i){return'<option value="'+i.id+'"'+(i.id===cur?' selected':'')+'>'+i.name+'</option>';}).join('');var filter=filterEl.value;var entries=purchaseLedger.filter(function(e){return filter==='all'||e.itemId===filter;});var div=document.getElementById('purchaseList');if(!entries.length){div.innerHTML='<p class="muted" style="font-size:13px">No purchases yet.</p>';return;}div.innerHTML=entries.map(function(e){var it=masterItems[e.itemId];var total=(e.qty*(e.pricePaid||0)).toFixed(2);return'<div class="irow"><div style="flex:1"><div style="font-weight:600;font-size:13px">'+(it?it.name:e.itemName||e.itemId)+'</div><div class="muted" style="font-size:12px">'+fmtDate(e.timestamp)+' - '+e.qty+' units @ $'+parseFloat(e.pricePaid||0).toFixed(3)+' - Total: $'+total+'</div></div><div style="display:flex;gap:6px"><button class="sm primary" data-action="editpurch" data-id="'+e.id+'">Edit</button><button class="danger sm" data-action="delpurch" data-id="'+e.id+'">Del</button></div></div>';}).join('');}

function renderHistory(){var filterLoc=document.getElementById('histLoc').value;var filtered=filterLoc==='all'?allReports:allReports.filter(function(r){return r.loc===filterLoc;});var div=document.getElementById('historyList');if(!filtered.length){div.innerHTML='<p class="muted" style="font-size:13px;padding:1rem 0">No reports yet.</p>';return;}div.innerHTML=filtered.map(function(r){var cSold=0,cRev=0,cProfit=0,hasAny=false;(r.lineItems||[]).forEach(function(l){var prev=getPrevRestockFor(r.id,l.itemId,l.slot);var arr=parseFloat(l.arrival);var sold=prev!==null&&!isNaN(prev)&&!isNaN(arr)?Math.max(0,prev-arr):null;var price=parseFloat(l.price)||0;var cost=warehouse[l.itemId]&&warehouse[l.itemId].avgCost?warehouse[l.itemId].avgCost:(masterItems[l.itemId]?masterItems[l.itemId].cost:0);if(sold!==null){cSold+=sold;cRev+=sold*price;cProfit+=sold*(price-cost);hasAny=true;}});return'<div class="hcard"><div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:.75rem;gap:8px"><div><div style="font-weight:700;font-size:15px">'+r.name+'</div><div class="muted" style="font-size:12px;margin-top:2px">'+r.date+'</div></div><div style="display:flex;gap:6px"><button class="sm primary" data-action="editreport" data-id="'+r.id+'">Edit</button><button class="danger sm" data-action="delreport" data-id="'+r.id+'">Del</button></div></div><div style="display:flex;gap:12px;font-size:13px;flex-wrap:wrap;margin-bottom:.75rem"><span><strong>'+(hasAny?cSold:'-')+'</strong> units</span><span><strong>'+(hasAny?'$'+cRev.toFixed(2):'-')+'</strong> rev</span>'+(hasAny?'<span class="'+(cProfit<0?'red':'green')+'"><strong>$'+cProfit.toFixed(2)+'</strong> profit</span>':'')+'</div><div>'+(r.lineItems||[]).map(function(l){var prev=getPrevRestockFor(r.id,l.itemId,l.slot);var arr=parseFloat(l.arrival);var sold=prev!==null&&!isNaN(prev)&&!isNaN(arr)?Math.max(0,prev-arr):null;return'<div class="hrow"><div><div style="font-weight:500">'+(l.item||l.itemId)+'</div><div class="muted" style="font-size:11px">Slot '+l.slot+(prev!==null?' prev: '+prev:'')+'</div></div><div style="display:flex;gap:5px;align-items:center"><span class="qb qa">'+(l.arrival||'-')+'</span><span class="muted">to</span><span class="qb qr">'+(l.restock||'-')+'</span><span class="muted">-</span><span class="qb qs">'+(sold!==null?sold+' sold':'-')+'</span></div></div>';}).join('')+'</div></div>';}).join('');}

function getSelectedMonths(){var sel=[];document.querySelectorAll('.mcb:checked').forEach(function(cb){sel.push(cb.value);});return sel;}
function populateMonthPills(){var keys=new Set(allReports.map(function(r){return r.monthKey;}));var today=new Date();keys.add(today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0'));var sorted=Array.from(keys).sort().reverse();var checked=new Set();document.querySelectorAll('.mcb:checked').forEach(function(cb){checked.add(cb.value);});if(!checked.size&&sorted.length)checked.add(sorted[0]);var c=document.getElementById('monthPills');c.innerHTML=sorted.map(function(k){var p=k.split('-');var label=MONTHS[parseInt(p[1])-1]+' '+p[0];var on=checked.has(k);return'<label style="display:flex;align-items:center;padding:6px 12px;background:'+(on?'#1a6fc4':'#f4f4f0')+';color:'+(on?'#fff':'#1a1a1a')+';border-radius:99px;cursor:pointer;font-size:13px;font-weight:500;border:1.5px solid '+(on?'#1a6fc4':'#ddd')+';user-select:none"><input type="checkbox" class="mcb" value="'+k+'"'+(on?' checked':'')+' style="display:none"/>'+label+'</label>';}).join('');document.querySelectorAll('.mcb').forEach(function(cb){cb.parentElement.addEventListener('click',function(){cb.checked=!cb.checked;cb.parentElement.style.background=cb.checked?'#1a6fc4':'#f4f4f0';cb.parentElement.style.color=cb.checked?'#fff':'#1a1a1a';cb.parentElement.style.borderColor=cb.checked?'#1a6fc4':'#ddd';var cnt=document.querySelectorAll('.mcb:checked').length;var el=document.getElementById('monthCount');if(el)el.textContent=cnt?'('+cnt+')':'';renderMonthly();});});var cnt=document.querySelectorAll('.mcb:checked').length;var el=document.getElementById('monthCount');if(el)el.textContent=cnt?'('+cnt+')':'';}
document.getElementById('selAllMonths').addEventListener('click',function(){document.querySelectorAll('.mcb').forEach(function(cb){cb.checked=true;cb.parentElement.style.background='#1a6fc4';cb.parentElement.style.color='#fff';cb.parentElement.style.borderColor='#1a6fc4';});renderMonthly();});
document.getElementById('clrAllMonths').addEventListener('click',function(){document.querySelectorAll('.mcb').forEach(function(cb){cb.checked=false;cb.parentElement.style.background='#f4f4f0';cb.parentElement.style.color='#1a1a1a';cb.parentElement.style.borderColor='#ddd';});renderMonthly();});
document.getElementById('monthLoc').addEventListener('change',renderMonthly);
function renderMonthly(){var sel=getSelectedMonths();var filterLoc=document.getElementById('monthLoc').value;var div=document.getElementById('monthlyContent');if(!sel.length){div.innerHTML='<div class="card"><p class="muted" style="font-size:13px">Select months above.</p></div>';return;}var label=sel.length===1?(function(){var p=sel[0].split('-');return MONTHS[parseInt(p[1])-1]+' '+p[0];})():sel.length+' months';var filtered=allReports.filter(function(r){return sel.includes(r.monthKey)&&(filterLoc==='all'||r.loc===filterLoc);});var itemMap={};filtered.forEach(function(r){(r.lineItems||[]).forEach(function(l){if(!l.item&&!l.itemId)return;var prev=getPrevRestockFor(r.id,l.itemId,l.slot);var arrival=parseFloat(l.arrival);var sold=prev!==null&&!isNaN(prev)&&!isNaN(arrival)?Math.max(0,prev-arrival):null;if(sold===null)return;var price=parseFloat(l.price)||0;var cost=warehouse[l.itemId]&&warehouse[l.itemId].avgCost?warehouse[l.itemId].avgCost:(masterItems[l.itemId]?masterItems[l.itemId].cost:parseFloat(l.cost)||0);var key=(l.itemId||l.item).toLowerCase();if(!itemMap[key])itemMap[key]={name:l.item||l.itemId,sold:0,rev:0,profit:0,visits:0};itemMap[key].sold+=sold;itemMap[key].rev+=sold*price;itemMap[key].profit+=sold*(price-cost);if(sold>0)itemMap[key].visits++;});});var items=Object.values(itemMap).sort(function(a,b){return b.sold-a.sold;});var tSold=items.reduce(function(s,i){return s+i.sold;},0);var tRev=items.reduce(function(s,i){return s+i.rev;},0);var tProfit=items.reduce(function(s,i){return s+i.profit;},0);var maxSold=items.length?Math.max(items[0].sold,1):1;if(!items.length){div.innerHTML='<div class="card"><p class="muted" style="font-size:13px">No data for '+label+'.</p></div>';return;}var top=items.slice(0,Math.min(3,items.length));var bot=items.length>3?items.slice(-Math.min(3,items.length)).reverse():[];div.innerHTML='<div class="stat-grid"><div class="stat"><div class="stat-label">Units sold</div><div class="stat-value">'+tSold+'</div></div><div class="stat"><div class="stat-label">Revenue</div><div class="stat-value">$'+tRev.toFixed(2)+'</div></div><div class="stat"><div class="stat-label">Profit</div><div class="stat-value '+(tProfit<0?'red':'green')+'">$'+tProfit.toFixed(2)+'</div></div><div class="stat"><div class="stat-label">Visits</div><div class="stat-value">'+filtered.length+'</div></div></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:.75rem"><div class="card" style="border-color:#2d7a2d"><h3 style="color:#1a6b2a;margin-bottom:.5rem">Top sellers</h3>'+top.map(function(it){return'<div style="margin-bottom:8px"><div style="display:flex;justify-content:space-between;font-size:13px"><span style="font-weight:600">'+it.name+'</span><span class="green">'+it.sold+'</span></div><div class="bar-wrap"><div class="bar" style="width:'+Math.round(it.sold/maxSold*100)+'%;background:#2d7a2d"></div></div></div>';}).join('')+'</div>'+(bot.length?'<div class="card" style="border-color:#c0392b"><h3 style="color:#a32d2d;margin-bottom:.5rem">Slowest</h3>'+bot.map(function(it){return'<div style="margin-bottom:8px"><div style="display:flex;justify-content:space-between;font-size:13px"><span style="font-weight:600">'+it.name+'</span><span class="red">'+it.sold+'</span></div><div class="bar-wrap"><div class="bar" style="width:'+Math.round(it.sold/maxSold*100)+'%;background:#c0392b"></div></div></div>';}).join('')+'</div>':'')+'</div><div class="card"><h2 style="margin-bottom:.75rem">All items - '+label+'</h2>'+items.map(function(it,i){var margin=it.rev>0?Math.round(it.profit/it.rev*100):null;return'<div class="mrow"><div><div style="font-weight:'+(i<3?'700':'400')+';font-size:14px">'+it.name+'</div><div class="muted" style="font-size:11px">'+it.visits+' visits - '+it.sold+' units</div></div><div style="display:flex;gap:10px;align-items:center;flex-shrink:0"><div style="text-align:right"><div style="font-size:13px;font-weight:600">$'+it.rev.toFixed(2)+'</div><div style="font-size:11px" class="'+(it.profit<0?'red':'green')+'">$'+it.profit.toFixed(2)+' profit</div></div><span style="padding:3px 8px;border-radius:99px;font-size:12px;font-weight:700;background:#f4f4f0">'+(margin!==null?margin+'%':'-')+'</span></div></div>';}).join('')+'</div>';}

document.getElementById('locSel').addEventListener('change',function(){loc=this.value;if(editingReportId){editingReportId=null;document.getElementById('submitBtn').innerHTML='Submit Report';document.getElementById('submitBtn').style.background='';document.getElementById('submitBtn').style.borderColor='';}loadSlots();});
