document.getElementById('addSlotBtn').addEventListener('click',function(){slots.push({slot:'',itemId:'',arrival:'',restock:'',price:'',cost:''});renderAll();});
document.getElementById('submitBtn').addEventListener('click',function(){var dateVal=document.getElementById('visitDate').value;if(!dateVal){alert('Select a visit date.');return;}var btn=document.getElementById('submitBtn');btn.disabled=true;btn.textContent='Saving...';var d=new Date(dateVal+'T12:00:00');var dateLabel=MONTHS[d.getMonth()]+' '+d.getDate()+', '+d.getFullYear();var monthKey=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');var locName=locations[loc]?locations[loc].name:'Location';var totSold=0,totRev=0,totProfit=0;var lineItems=slots.filter(function(s){return s.itemId||s.slot;}).map(function(s){var r=calcRow(s);var prev=getPrevRestock(s.slot,s.itemId);var it=s.itemId&&masterItems[s.itemId]?masterItems[s.itemId]:null;if(r.sold!==null){totSold+=r.sold;totRev+=r.rev;totProfit+=r.profit;}var autoC=warehouse[s.itemId]&&warehouse[s.itemId].avgCost?warehouse[s.itemId].avgCost:(it?it.cost:parseFloat(s.cost)||0);return{slot:s.slot,itemId:s.itemId,item:it?it.name:s.itemId,arrival:s.arrival,restock:s.restock,prevRestock:prev!==null?prev:null,price:parseFloat(s.price)||0,cost:autoC,sold:r.sold,rev:r.rev,profit:r.profit};});var reportData={date:dateLabel,dateVal:dateVal,monthKey:monthKey,loc:loc,name:locName,lineItems:lineItems,totSold:totSold,totRev:totRev,totProfit:totProfit,timestamp:Date.now()};function finishSubmit(){clearBackup();showStatus('Report saved for '+locName,'success');document.getElementById('submitBtn').innerHTML='Submit Report';document.getElementById('submitBtn').style.background='';document.getElementById('submitBtn').style.borderColor='';btn.disabled=false;loadAllReports().then(function(){buildPrevRestockMap();renderAll();showPrevRestockNote();showTab('history');});}if(!isOnline){offlineQueue.push({type:'report',data:reportData});saveQueue();clearBackup();showStatus('Offline - report queued!','error');btn.disabled=false;btn.innerHTML='Submit Report';return;}var p=editingReportId?fbDel('reports',editingReportId):Promise.resolve();editingReportId=null;p.then(function(){return fbAdd('reports',reportData);}).then(function(){return saveSlotsDB();}).then(function(){var updates=[];lineItems.forEach(function(l){if(!l.itemId)return;var arrival=parseFloat(l.arrival);var restock=parseFloat(l.restock);var loaded=(!isNaN(restock)&&!isNaN(arrival))?Math.max(0,restock-arrival):0;if(!isNaN(restock)&&restock>=0){if(!machines[loc])machines[loc]={id:loc};if(!machines[loc][l.itemId])machines[loc][l.itemId]={itemId:l.itemId,qty:0};machines[loc][l.itemId].qty=restock;updates.push(fbSet('machines',loc,machines[loc]));}if(loaded>0&&warehouse[l.itemId]){warehouse[l.itemId].qty=Math.max(0,warehouse[l.itemId].qty-loaded);updates.push(fbSet('warehouse',l.itemId,warehouse[l.itemId]));}});return Promise.all(updates);}).then(finishSubmit).catch(function(e){showStatus('Error: '+e.message,'error');btn.disabled=false;btn.innerHTML='Submit Report';});});

document.getElementById('moveStockBtn').addEventListener('click',function(){var items=Object.values(masterItems).sort(function(a,b){return a.name.localeCompare(b.name);});var opts='<option value="">-- Select --</option>'+items.map(function(i){return'<option value="'+i.id+'">'+i.name+'</option>';}).join('');['mvFromItem','swItem1','swItem2','rpOldItem','rpNewItem'].forEach(function(id){var el=document.getElementById(id);if(el)el.innerHTML=opts;});showMoveStep('step1');document.getElementById('moveModal').style.display='block';});
document.getElementById('closeMoveModal').addEventListener('click',function(){document.getElementById('moveModal').style.display='none';});
function showMoveStep(s){['step1','move','swap','replace'].forEach(function(n){var el=document.getElementById(n==='step1'?'moveStep1':'moveStep2'+n);if(el)el.style.display=s===n?'':'none';});}
document.querySelectorAll('[data-movetype]').forEach(function(btn){btn.addEventListener('click',function(){showMoveStep(btn.getAttribute('data-movetype'));});});
document.getElementById('mvBackMove').addEventListener('click',function(){showMoveStep('step1');});
document.getElementById('mvBackSwap').addEventListener('click',function(){showMoveStep('step1');});
document.getElementById('mvBackReplace').addEventListener('click',function(){showMoveStep('step1');});
document.getElementById('mvApplyMove').addEventListener('click',function(){var fs=document.getElementById('mvFromSlot').value.trim();var fi=document.getElementById('mvFromItem').value;var fq=document.getElementById('mvFromQty').value;var ts=document.getElementById('mvToSlot').value.trim();var tq=document.getElementById('mvToQty').value;var sp=document.getElementById('mvPrice').value;if(!fs||!fi||!ts){alert('Fill in all fields.');return;}var it=masterItems[fi];var price=parseFloat(sp)||(it?it.price:0);var cost=warehouse[fi]&&warehouse[fi].avgCost?warehouse[fi].avgCost:(it?it.cost:0);slots.push({slot:fs,itemId:fi,arrival:fq,restock:'0',price:price,cost:cost});slots.push({slot:ts,itemId:fi,arrival:'0',restock:tq,price:price,cost:cost});renderAll();document.getElementById('moveModal').style.display='none';showToast('Move added!');});
document.getElementById('mvApplySwap').addEventListener('click',function(){var s1=document.getElementById('swSlot1').value.trim();var i1=document.getElementById('swItem1').value;var q1=document.getElementById('swQty1').value;var s2=document.getElementById('swSlot2').value.trim();var i2=document.getElementById('swItem2').value;var q2=document.getElementById('swQty2').value;if(!s1||!i1||!s2||!i2){alert('Fill in all fields.');return;}var it1=masterItems[i1];var it2=masterItems[i2];var c1=warehouse[i1]&&warehouse[i1].avgCost?warehouse[i1].avgCost:(it1?it1.cost:0);var c2=warehouse[i2]&&warehouse[i2].avgCost?warehouse[i2].avgCost:(it2?it2.cost:0);slots.push({slot:s1,itemId:i1,arrival:q1,restock:'0',price:it1?it1.price:0,cost:c1});slots.push({slot:s1,itemId:i2,arrival:'0',restock:q2,price:it2?it2.price:0,cost:c2});slots.push({slot:s2,itemId:i2,arrival:q2,restock:'0',price:it2?it2.price:0,cost:c2});slots.push({slot:s2,itemId:i1,arrival:'0',restock:q1,price:it1?it1.price:0,cost:c1});renderAll();document.getElementById('moveModal').style.display='none';showToast('Swap added!');});
document.getElementById('mvApplyReplace').addEventListener('click',function(){var sl=document.getElementById('rpSlot').value.trim();var oi=document.getElementById('rpOldItem').value;var oq=document.getElementById('rpOldQty').value;var ni=document.getElementById('rpNewItem').value;var nq=document.getElementById('rpNewQty').value;var np=document.getElementById('rpNewPrice').value;if(!sl||!oi||!ni){alert('Fill in all fields.');return;}var oit=masterItems[oi];var nit=masterItems[ni];var oc=warehouse[oi]&&warehouse[oi].avgCost?warehouse[oi].avgCost:(oit?oit.cost:0);var nc=warehouse[ni]&&warehouse[ni].avgCost?warehouse[ni].avgCost:(nit?nit.cost:0);slots.push({slot:sl,itemId:oi,arrival:oq,restock:'0',price:oit?oit.price:0,cost:oc});slots.push({slot:sl,itemId:ni,arrival:'0',restock:nq,price:parseFloat(np)||(nit?nit.price:0),cost:nc});renderAll();document.getElementById('moveModal').style.display='none';showToast('Replacement added!');});

document.getElementById('closeTemplateBtn').addEventListener('click',function(){document.getElementById('slotTemplateCard').style.display='none';editingTemplateLocId=null;templateSlots=[];});
document.getElementById('addTemplateSlotBtn').addEventListener('click',function(){templateSlots.push({slot:'',itemId:'',price:''});renderTemplateSlots();});
document.getElementById('saveTemplateBtn').addEventListener('click',function(){if(!editingTemplateLocId)return;var toSave=templateSlots.filter(function(s){return s.slot||s.itemId;}).map(function(s){return{slot:s.slot||'',itemId:s.itemId||'',price:parseFloat(s.price)||0,arrival:'',restock:''};});fbSet('slotTemplates',editingTemplateLocId,{locId:editingTemplateLocId,slots:toSave}).then(function(){slotTemplates[editingTemplateLocId]={id:editingTemplateLocId,locId:editingTemplateLocId,slots:toSave};if(editingTemplateLocId===loc){slots=toSave.map(function(s){return Object.assign({},s,{arrival:'',restock:'',cost:warehouse[s.itemId]&&warehouse[s.itemId].avgCost?warehouse[s.itemId].avgCost:''});});buildPrevRestockMap();renderAll();showPrevRestockNote();}showToast('Template saved!');document.getElementById('slotTemplateCard').style.display='none';editingTemplateLocId=null;templateSlots=[];});});
document.getElementById('importFromHistoryBtn').addEventListener('click',function(){if(!editingTemplateLocId)return;var reps=allReports.filter(function(r){return r.loc===editingTemplateLocId;}).sort(function(a,b){return b.timestamp-a.timestamp;});if(!reps.length){showToast('No history found.');return;}templateSlots=(reps[0].lineItems||[]).filter(function(l){return l.itemId||l.slot;}).map(function(l){var it=l.itemId&&masterItems[l.itemId]?masterItems[l.itemId]:null;return{slot:l.slot||'',itemId:l.itemId||'',price:parseFloat(l.price)||(it?it.price:0)};});document.getElementById('templateImportBar').style.display='none';renderTemplateSlots();showToast('Imported!');});
function renderTemplateSlots(){var c=document.getElementById('templateSlotList');if(!c)return;c.innerHTML=templateSlots.map(function(s,i){return'<div style="background:#f9f8f6;border:1.5px solid #e8e4de;border-radius:12px;padding:.75rem;margin-bottom:.5rem"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><span style="font-size:11px;font-weight:600;color:#888">SLOT '+(i+1)+'</span><button class="danger sm" data-action="removetslot" data-idx="'+i+'" style="background:transparent;color:#c0392b;border-color:#e8b4b0;padding:3px 8px">X</button></div><div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px"><div><label style="font-size:11px;color:#666;margin-bottom:3px;display:block">Slot label</label><input type="text" value="'+esc(s.slot)+'" placeholder="A1" data-tidx="'+i+'" data-tfield="slot"/></div><div><label style="font-size:11px;color:#666;margin-bottom:3px;display:block">Item</label><select data-tidx="'+i+'" data-tfield="itemId">'+itemOptsStr(s.itemId)+'</select></div><div><label style="font-size:11px;color:#666;margin-bottom:3px;display:block">Sell price ($)</label><input type="number" value="'+esc(s.price)+'" placeholder="2.00" step="0.25" min="0" inputmode="decimal" data-tidx="'+i+'" data-tfield="price"/></div></div></div>';}).join('');}

document.addEventListener('input',function(e){var inp=e.target.closest('[data-field]');if(inp&&inp.tagName!=='SELECT'){var i=parseInt(inp.dataset.idx);var f=inp.dataset.field;slots[i][f]=inp.value;buildPrevRestockMap();updateRowCalcs(i);renderTotals();saveBackup();}var tinp=e.target.closest('[data-tfield]');if(tinp&&tinp.tagName!=='SELECT'){var ti=parseInt(tinp.dataset.tidx);templateSlots[ti][tinp.dataset.tfield]=tinp.value;}});
document.addEventListener('change',function(e){var sel=e.target.closest('[data-field]');if(sel&&sel.tagName==='SELECT'){var i=parseInt(sel.dataset.idx);slots[i][sel.dataset.field]=sel.value;if(sel.dataset.field==='itemId'&&sel.value&&masterItems[sel.value]){var it=masterItems[sel.value];if(!slots[i].price)slots[i].price=it.price;if(warehouse[sel.value]&&warehouse[sel.value].avgCost)slots[i].cost=warehouse[sel.value].avgCost;else if(!slots[i].cost)slots[i].cost=it.cost;}buildPrevRestockMap();renderAll();}var tsel=e.target.closest('[data-tfield]');if(tsel&&tsel.tagName==='SELECT'){var ti=parseInt(tsel.dataset.tidx);templateSlots[ti][tsel.dataset.tfield]=tsel.value;if(tsel.dataset.tfield==='itemId'&&tsel.value&&masterItems[tsel.value]){var tit=masterItems[tsel.value];if(!templateSlots[ti].price)templateSlots[ti].price=tit.price;renderTemplateSlots();}}});
document.addEventListener('click',function(e){var btn=e.target.closest('[data-action]');if(!btn)return;var action=btn.getAttribute('data-action');var id=btn.getAttribute('data-id');var idx=btn.getAttribute('data-idx');
if(action==='removeslot'){if(confirm('Remove slot?')){slots.splice(parseInt(idx),1);renderAll();}}
if(action==='removetslot'){templateSlots.splice(parseInt(idx),1);renderTemplateSlots();}
if(action==='delreport'){if(!confirm('Delete this report?'))return;fbDel('reports',id).then(function(){return loadAllReports();}).then(function(){buildPrevRestockMap();renderAll();showPrevRestockNote();renderHistory();showToast('Report deleted.');});}
if(action==='editreport'){var rep=allReports.find(function(r){return r.id===id;});if(!rep)return;if(!confirm('Load into Visit Sheet to correct and resubmit?'))return;editingReportId=rep.id;loc=rep.loc;document.getElementById('locSel').value=loc;if(rep.dateVal)document.getElementById('visitDate').value=rep.dateVal;slots=(rep.lineItems||[]).map(function(l){return{slot:l.slot||'',itemId:l.itemId||'',arrival:l.arrival||'',restock:l.restock||'',price:l.price||'',cost:l.cost||''};});buildPrevRestockMap();renderAll();showPrevRestockNote();document.getElementById('submitBtn').innerHTML='Update Report';document.getElementById('submitBtn').style.background='#d4680a';document.getElementById('submitBtn').style.borderColor='#d4680a';showTab('sheet');showStatus('Editing report from '+rep.date,'info');}
if(action==='editloc'){var el=locations[id];if(!el)return;editingLocId=id;document.getElementById('locNameInput').value=el.name;document.getElementById('locAddress').value=el.address||'';document.getElementById('locFormTitle').textContent='Edit location';document.getElementById('saveLocBtn').textContent='Save changes';document.getElementById('cancelLocBtn').style.display='';document.getElementById('pane-locations').scrollIntoView({behavior:'smooth',block:'start'});}
if(action==='delloc'){var dl=locations[id];if(!confirm('Delete "'+dl.name+'"?'))return;fbDel('locations',id).then(function(){delete locations[id];if(loc===id)loc=Object.keys(locations).sort()[0]||'';updateLocDropdowns();renderLocationList();showToast('Deleted.');});}
if(action==='slots'){editingTemplateLocId=id;var lName=locations[id]?locations[id].name:'Location';document.getElementById('templateLocName').textContent=lName;templateSlots=slotTemplates[id]&&slotTemplates[id].slots&&slotTemplates[id].slots.length?JSON.parse(JSON.stringify(slotTemplates[id].slots)):[{slot:'A1',itemId:'',price:''},{slot:'A2',itemId:'',price:''},{slot:'B1',itemId:'',price:''},{slot:'B2',itemId:'',price:''}];var reps=allReports.filter(function(r){return r.loc===id;}).sort(function(a,b){return b.timestamp-a.timestamp;});var impBar=document.getElementById('templateImportBar');if(reps.length){var cnt=(reps[0].lineItems||[]).filter(function(l){return l.itemId||l.item;}).length;document.getElementById('templateImportDesc').textContent='Last visit '+reps[0].date+' had '+cnt+' slots.';impBar.style.display='';}else{impBar.style.display='none';}document.getElementById('slotTemplateCard').style.display='';document.getElementById('slotTemplateCard').scrollIntoView({behavior:'smooth',block:'start'});renderTemplateSlots();}
if(action==='edititem'){var it=masterItems[id];if(!it)return;editingItemId=id;document.getElementById('masterName').value=it.name;document.getElementById('masterCat').value=it.category;document.getElementById('masterPrice').value=it.price;document.getElementById('masterCost').value=it.cost;document.getElementById('masterReorder').value=it.reorder||0;document.getElementById('itemFormTitle').textContent='Edit item';document.getElementById('saveItemBtn').textContent='Save changes';document.getElementById('cancelItemBtn').style.display='';}
if(action==='delitem'){var dit=masterItems[id];var inWh=warehouse[id]&&warehouse[id].qty>0;var inMach=Object.values(machines).some(function(m){return m[id]&&m[id].qty>0;});if(!confirm((inWh||inMach?'Has stock — delete anyway?':'Delete "'+dit.name+'"?')))return;var dels=[fbDel('masterItems',id)];if(inWh)dels.push(fbDel('warehouse',id));if(inMach)Object.keys(machines).forEach(function(lk){if(machines[lk][id]){delete machines[lk][id];dels.push(fbSet('machines',lk,machines[lk]));}});Promise.all(dels).then(function(){delete masterItems[id];if(inWh)delete warehouse[id];updateItemDropdowns();renderMasterItems();showToast('Deleted.');});}
if(action==='editinv'){var it=masterItems[id];if(!it)return;var wh=warehouse[id]||{qty:0};var mach=0;Object.values(machines).forEach(function(m){if(m[id])mach+=m[id].qty;});var choice=prompt('Edit warehouse qty for '+it.name+'\nWarehouse: '+wh.qty+' | Machines: '+mach+'\n\nNew qty (or +/- to adjust):',wh.qty);if(choice===null)return;var nq=String(choice).startsWith('+')||String(choice).startsWith('-')?Math.max(0,wh.qty+parseInt(choice)):Math.max(0,parseInt(choice));if(isNaN(nq)){alert('Invalid number.');return;}var ex=warehouse[id]||{id:id,qty:0,avgCost:it.cost||0,reorder:it.reorder||0};ex.qty=nq;warehouse[id]=ex;fbSet('warehouse',id,ex).then(function(){renderInventory();showToast('Updated!');});}
if(action==='editpurch'){var pe=purchaseLedger.find(function(e){return e.id===id;});if(!pe)return;var pit=masterItems[pe.itemId];var nq=prompt('New qty ('+(pit?pit.name:pe.itemId)+'):\nCurrent: '+pe.qty,pe.qty);if(nq===null)return;var np=prompt('New price per unit ($):',parseFloat(pe.pricePaid||0).toFixed(3));if(np===null)return;var q=parseInt(nq);var p=parseFloat(np);if(isNaN(q)||q<1||isNaN(p)){alert('Invalid.');return;}pe.qty=q;pe.pricePaid=p;fbSet('purchaseLedger',id,pe).then(function(){return recalcAvgCost(pe.itemId);}).then(function(){renderPurchaseList();renderInventory();showToast('Updated!');});}
if(action==='delpurch'){var de=purchaseLedger.find(function(e){return e.id===id;});if(!de)return;if(!confirm('Delete this purchase? Avg cost will recalculate.'))return;fbDel('purchaseLedger',id).then(function(){purchaseLedger=purchaseLedger.filter(function(e){return e.id!==id;});if(warehouse[de.itemId]){warehouse[de.itemId].qty=Math.max(0,warehouse[de.itemId].qty-de.qty);return Promise.all([fbSet('warehouse',de.itemId,warehouse[de.itemId]),recalcAvgCost(de.itemId)]);}}).then(function(){renderPurchaseList();renderInventory();showToast('Deleted.');});}
});

isOnline=navigator.onLine;updateConn();loadQueue();
document.getElementById('visitDate').value=new Date().toISOString().split('T')[0];
showStatus('Connecting...','info');
window.addEventListener('online',function(){isOnline=true;updateConn();syncQueue();});
window.addEventListener('offline',function(){isOnline=false;updateConn();});
Promise.all([loadLocations(),loadSlotTemplates(),loadPurchaseLedger(),loadMasterItems(),loadWarehouse(),loadMachines(),loadAllReports()]).then(function(){updateLocDropdowns();updateItemDropdowns();return loadSlots();}).then(function(){loadBackup();populateMonthPills();showStatus('Connected!','success');if(offlineQueue.length>0&&isOnline){setTimeout(syncQueue,2000);}}).catch(function(e){showStatus('Error: '+e.message,'error');});
